// END GENERATED FONT DATA

struct RETRO_FontData {
	const unsigned char *data;
	int width;
	int height;
	int bytesperrow;
	const unsigned char *widths = nullptr; // per-character advance; null means fixed-width
};

struct RETRO_FontAsset {
	const char *filename;
	int width;
	int height;
	int firstcharacter = 32;
};

// A font normalized to one horizontal atlas of fixed-width glyph cells,
// character firstcharacter at cell 0, however it started out. widths holds
// the same optional per-character advance override as RETRO_FontData; null
// means every glyph advances by width.
struct RETRO_Font {
	RETRO_Image *atlas;
	int width;
	int height;
	int firstcharacter;
	const unsigned char *widths = nullptr;
};

static const RETRO_FontData RETRO_FONT_VGA_8X8 = {
	&RETRO_FONT_VGA_8X8_DATA[0][0][0], 8, 8, 1
};
static const RETRO_FontData RETRO_FONT_TOPAZ13_8X8 = {
	&RETRO_FONT_TOPAZ13_8X8_DATA[0][0][0], 8, 8, 1
};
static const RETRO_FontData RETRO_FONT_TOPAZ30_8X8 = {
	&RETRO_FONT_TOPAZ30_8X8_DATA[0][0][0], 8, 8, 1
};
static const RETRO_FontData RETRO_FONT_MINECRAFT_8X8 = {
	&RETRO_FONT_MINECRAFT_8X8_DATA[0][0][0], 8, 8, 1, &RETRO_FONT_MINECRAFT_8X8_WIDTHS[0]
};

static RETRO_FontData RETRO_CurrentFont = RETRO_FONT_VGA_8X8;

void RETRO_SetFont(const RETRO_FontData &font)
{
	RETRO_CurrentFont = font;
}

inline const unsigned char *RETRO_Glyph(unsigned char character)
{
	if (character >= 128) {
		return NULL;
	}
	return RETRO_CurrentFont.data + character * RETRO_CurrentFont.height * RETRO_CurrentFont.bytesperrow;
}

inline bool RETRO_GlyphPixel(const unsigned char *glyph, int x, int y)
{
	return glyph[y * RETRO_CurrentFont.bytesperrow + x / 8] & (1 << (x % 8));
}

inline int RETRO_CharWidth(unsigned char character)
{
	return (RETRO_CurrentFont.widths && character < 128) ? RETRO_CurrentFont.widths[character] : RETRO_CurrentFont.width;
}

inline int RETRO_CharWidth(const RETRO_FontData &font, unsigned char character)
{
	return (font.widths && character < 128) ? font.widths[character] : font.width;
}

inline int RETRO_CharWidth(const RETRO_FontAsset &font, unsigned char character)
{
	return font.width;
}

inline int RETRO_CharWidth(const RETRO_Font &font, unsigned char character)
{
	return (font.widths && character < 128) ? font.widths[character] : font.width;
}

void RETRO_PutChar(unsigned char character, int x, int y, unsigned char color)
{
	const unsigned char *glyph = RETRO_Glyph(character);
	if (glyph == NULL) {
		return;
	}

	for (int yy = 0; yy < RETRO_CurrentFont.height; yy++) {
		for (int xx = 0; xx < RETRO_CurrentFont.width; xx++) {
			if (RETRO_GlyphPixel(glyph, xx, yy)) {
				RETRO_PutPixel(x + xx, y + yy, color);
			}
		}
	}
}

void RETRO_PutString(const char *text, int x, int y, unsigned char color)
{
	while (*text != 0) {
		unsigned char character = *text++;
		RETRO_PutChar(character, x, y, color);
		x += RETRO_CharWidth(character);
	}
}

// Normalize a compiled-in bitmap font into a RETRO_Font: a fresh atlas image
// covering all 128 character slots, one width-wide cell per code, unpacked
// from the source's 1-bit rows into 0/255 texels. Palette index 0 is black,
// 255 is white, and every other index is copied from the active palette.
RETRO_Font RETRO_LoadFont(const RETRO_FontData &font)
{
	const int glyphs = 128;

	RETRO_Image *atlas = RETRO_AllocateImage();
	atlas->width = font.width * glyphs;
	atlas->height = font.height;
	atlas->data = (unsigned char *)calloc(atlas->width * atlas->height, 1);
	if (atlas->data == NULL) {
		RETRO_RageQuit("Cannot allocate font atlas memory\n");
	}
	for (int color = 0; color < RETRO_COLORS; color++) {
		atlas->palette[color] = RETRO_GetColor(color);
	}
	atlas->palette[0] = RETRO_Palette{ 0, 0, 0 }; // background defaults to black
	atlas->palette[255] = RETRO_Palette{ 255, 255, 255 }; // set font pixels default to white, not whatever color 255 happened to be

	for (int character = 0; character < glyphs; character++) {
		const unsigned char *glyph = font.data + character * font.height * font.bytesperrow;

		for (int y = 0; y < font.height; y++) {
			for (int x = 0; x < font.width; x++) {
				if (glyph[y * font.bytesperrow + x / 8] & (1 << (x % 8))) {
					atlas->data[y * atlas->width + character * font.width + x] = 255;
				}
			}
		}
	}

	return RETRO_Font{ atlas, font.width, font.height, 0, font.widths };
}

// Normalize a horizontal PCX font atlas into a RETRO_Font. The atlas is
// used as loaded, palette and all nonzero texel values preserved verbatim;
// index zero remains transparent.
RETRO_Font RETRO_LoadFont(const RETRO_FontAsset &font)
{
	RETRO_Image *atlas = RETRO_LoadImage(font.filename);
	return RETRO_Font{ atlas, font.width, font.height, font.firstcharacter, nullptr };
}

// Pixel size of one line as RETRO_GenerateTextImage would pack it: each
// glyph advances by its character width plus spacing, then both are scaled.
inline int RETRO_TextLineWidth(const RETRO_Font &font, const char *line, int scale = 1, int spacing = 0)
{
	if (line == NULL) {
		return 0;
	}
	int linewidth = 0;
	for (const char *scan = line; *scan != 0; scan++) {
		linewidth += (RETRO_CharWidth(font, (unsigned char)*scan) + spacing) * scale;
	}
	return linewidth;
}

inline int RETRO_TextImageWidth(const RETRO_Font &font, const char *const *lines, int rows, int scale = 1, int spacing = 0)
{
	int width = 0;
	for (int row = 0; row < rows; row++) {
		width = MAX(width, RETRO_TextLineWidth(font, lines[row], scale, spacing));
	}
	return width;
}

inline int RETRO_TextImageHeight(const RETRO_Font &font, int rows, int scale = 1)
{
	return font.height * scale * rows;
}

// Unpack an array of lines into an allocated 8-bit image, glyph after glyph
// in the order given, repeats and all. Each line is centered within the
// widest one. A null slot is an empty row. The loaded font's palette and
// all nonzero atlas texels are carried through unchanged; index zero
// remains transparent. spacing adds unscaled font pixels of gap after every
// glyph, including the last, so a caller can wrap the width the same way
// regardless of spacing.
RETRO_Image *RETRO_GenerateTextImage(const RETRO_Font &font, const char *const *lines, int rows, int scale = 1, int spacing = 0)
{
	int width = RETRO_TextImageWidth(font, lines, rows, scale, spacing);
	int height = RETRO_TextImageHeight(font, rows, scale);

	RETRO_Image *image = RETRO_AllocateImage();
	image->width = width;
	image->height = height;
	image->data = (unsigned char *)calloc(width * height, 1);
	if (image->data == NULL) {
		RETRO_RageQuit("Cannot allocate text strip memory\n");
	}
	for (int color = 0; color < RETRO_COLORS; color++) {
		image->palette[color] = font.atlas->palette[color];
	}

	for (int row = 0; row < rows; row++) {
		if (lines[row] == NULL) {
			continue;
		}
		const char *line = lines[row];
		int linewidth = RETRO_TextLineWidth(font, line, scale, spacing);
		int cursor = (width - linewidth) / 2;
		int rowbase = row * font.height * scale;

		while (*line != 0) {
			int character = (unsigned char)*line++;
			int glyph = character - font.firstcharacter;
			int sourcex = glyph * font.width;

			if (glyph >= 0 && sourcex + font.width <= font.atlas->width && font.height <= font.atlas->height) {
				int copywidth = MIN(font.width, RETRO_CharWidth(font, (unsigned char)character));
				for (int y = 0; y < font.height; y++) {
					for (int x = 0; x < copywidth; x++) {
						unsigned char color = font.atlas->data[y * font.atlas->width + sourcex + x];
						if (color == 0) {
							continue;
						}
						for (int yy = 0; yy < scale; yy++) {
							for (int xx = 0; xx < scale; xx++) {
								int destx = cursor + x * scale + xx;
								if (destx < 0 || destx >= width) {
									continue;
								}
								image->data[(rowbase + y * scale + yy) * width + destx] = color;
							}
						}
					}
				}
			}
			cursor += (RETRO_CharWidth(font, (unsigned char)character) + spacing) * scale;
		}
	}

	return image;
}

